require_once __DIR__.'/_header.php'; $id=(int)($_GET['id']??0); $st=db()->prepare('SELECT * FROM videos WHERE id=?');$st->execute([$id]);$v=$st->fetch();if(!$v){exit('Not found');}$cats=db()->query("SELECT * FROM categories WHERE status=1 ORDER BY name")->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$title=trim($_POST['title']);$desc=trim($_POST['description']);$cat=(int)$_POST['category_id'];$status=$_POST['status'];$r2=trim($_POST['r2_key']??'');$hls=trim($_POST['hls_master_key']??'');$duration=max(0,(int)($_POST['duration_seconds']??0));db()->prepare('UPDATE videos SET title=?,description=?,category_id=?,r2_key=?,hls_master_key=?,duration_seconds=?,status=? WHERE id=?')->execute([$title,$desc,$cat?:null,$r2?:null,$hls?:null,$duration?:null,$status,$id]);log_action('video.update','video_id='.$id);header('Location: video-edit.php?id='.$id);exit;}
$tok=db()->prepare('SELECT * FROM embed_tokens WHERE video_id=? AND status=1 LIMIT 1');$tok->execute([$id]);$token=$tok->fetch();
